package yks

import yks.utils.*
import yks.types.*
import kotlin.test.*

/**
 * Wire compatibility tests for snapshots, relative positions, and state vectors
 * against binary fixtures generated by JavaScript yjs 13.6.30.
 *
 * Fixtures generated by fixtures/generate.mjs using yjs npm package.
 *
 * NOTE on relative position encoding: yjs uses a single-tag format where the first
 * varUint encodes both the item/type decision:
 *   tag=0 -> has item (read item ID, then assoc)
 *   tag=1 -> has tname (read varString, then assoc)
 *   tag=2 -> has type ID (read type ID, then assoc)
 * The Kotlin port must match this format for wire compatibility.
 */
class WireCompatSnapshotTest {

    private fun hexToBytes(hex: String): ByteArray {
        val result = ByteArray(hex.length / 2)
        for (i in result.indices) {
            result[i] = hex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }
        return result
    }

    private fun toHex(bytes: ByteArray): String {
        return bytes.joinToString("") {
            val v = it.toInt() and 0xFF
            val hi = v shr 4
            val lo = v and 0x0F
            "${HEX_CHARS[hi]}${HEX_CHARS[lo]}"
        }
    }

    companion object {
        private const val HEX_CHARS = "0123456789abcdef"
    }

