    // Snapshot Tests
    // =========================================================================

    @Test
    fun testSnapshotArrayDecode() {
        // Decode the yjs snapshot and verify its contents
        val snap = decodeSnapshot(hexToBytes(WireCompatFixtures.SNAPSHOTS_SNAPSHOT_ARRAY_SNAPSHOT_V1))
        assertEquals(1, snap.sv.size, "snapshot should have 1 client")
        assertEquals(3, snap.sv[301], "client 301 should have clock 3")
        assertTrue(snap.ds.clients.isEmpty(), "delete set should be empty")
    }

    @Test
    fun testSnapshotArrayEncodeRoundTrip() {
        val originalBytes = hexToBytes(WireCompatFixtures.SNAPSHOTS_SNAPSHOT_ARRAY_SNAPSHOT_V1)
        val snap = decodeSnapshot(originalBytes)
        val reencoded = encodeSnapshot(snap)
        val snap2 = decodeSnapshot(reencoded)
        assertTrue(equalSnapshots(snap, snap2), "re-encoded snapshot should decode to equal snapshot")
    }

    @Test
    fun testSnapshotArrayByteExact() {
        // Single-client snapshot with empty delete set: no ordering ambiguity
        val expectedHex = WireCompatFixtures.SNAPSHOTS_SNAPSHOT_ARRAY_SNAPSHOT_V1
        val snap = decodeSnapshot(hexToBytes(expectedHex))
        val reencoded = toHex(encodeSnapshot(snap))
        assertEquals(expectedHex, reencoded,
            "snapshot encoding should be byte-exact for single-client snapshot")
    }

    @Test
    fun testSnapshotArrayRestore() {
        // Apply fullUpdateAfter to get the complete post-mutation doc (gc=false to keep all structs)
        val originDoc = Doc(gc = false)
        applyUpdate(originDoc, hexToBytes(WireCompatFixtures.SNAPSHOTS_SNAPSHOT_ARRAY_FULL_UPDATE_AFTER))

        // Decode the snapshot taken at the "before" state
        val snap = decodeSnapshot(hexToBytes(WireCompatFixtures.SNAPSHOTS_SNAPSHOT_ARRAY_SNAPSHOT_V1))

        // Restore from snapshot
        val restoredDoc = createDocFromSnapshot(originDoc, snap)
        val arr = restoredDoc.getArray("arr")
        assertEquals(3, arr.length, "restored array should have 3 elements")
        assertEquals(listOf(1, 2, 3), arr.toArray(), "restored array should be [1, 2, 3]")
    }

