    // =========================================================================
    // Relative Position Tests
    //
    // yjs encodes relative positions as a single-tag format:
    //   tag=0: item exists -> readID(item), then readVarInt(assoc)
    //   tag=1: tname exists (position at type boundary) -> readVarString(tname), then readVarInt(assoc)
    //   tag=2: type ID exists -> readID(type), then readVarInt(assoc)
    // =========================================================================

    @Test
    fun testRposTextMiddleDecodeYjsBytes() {
        // yjs hex: "0091030500"
        // tag=0 (has item), item=ID(401,5), assoc=0
        val rpos = decodeRelativePosition(
            hexToBytes(WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_ENCODED_RPOS)
        )
        assertNotNull(rpos.item, "rpos should reference an item")
        assertEquals(401, rpos.item.client, "rpos item client should be 401")
        assertEquals(5, rpos.item.clock, "rpos item clock should be 5")
        assertEquals(0, rpos.assoc, "assoc should be 0")
    }

    @Test
    fun testRposTextMiddleEncodeMatchesYjs() {
        // Build doc with "Hello World", create rpos at index 5
        val doc = Doc(gc = false)
        applyUpdate(doc, hexToBytes(WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_FULL_UPDATE_BEFORE))

        val text = doc.getText("text")
        assertEquals(11, text.length, "text should be 11 chars")

        val rpos = createRelativePositionFromTypeIndex(
            text,
            WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_INDEX_BEFORE,
            WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_ASSOC
        )
        val encoded = toHex(encodeRelativePosition(rpos))
        assertEquals(
            WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_ENCODED_RPOS, encoded,
            "encoded rpos should match yjs bytes"
        )
    }

    @Test
    fun testRposTextMiddleResolveAfterMutation() {
        // Apply the full post-mutation state
        val doc = Doc(gc = false)
        applyUpdate(doc, hexToBytes(WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_FULL_UPDATE_AFTER))

        // Decode the yjs relative position
        val rpos = decodeRelativePosition(
            hexToBytes(WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_ENCODED_RPOS)
        )

        // Resolve
        val absPos = createAbsolutePositionFromRelativePosition(rpos, doc)
        assertNotNull(absPos, "should resolve to an absolute position")
        assertEquals(
            WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_RESOLVED_INDEX_AFTER,
            absPos.index,
            "resolved index after inserting 'XXX' at start should shift from 5 to 8"
        )
    }

