        val rposHexValues = listOf(
            WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_MIDDLE_ENCODED_RPOS,
            WireCompatFixtures.RELATIVE_POSITIONS_RPOS_TEXT_START_ENCODED_RPOS,
