            WireCompatFixtures.RELATIVE_POSITIONS_RPOS_AFTER_DELETE_ENCODED_RPOS
        )
        for (hex in rposHexValues) {
            val rpos = decodeRelativePosition(hexToBytes(hex))
            val reencoded = toHex(encodeRelativePosition(rpos))
            assertEquals(hex, reencoded, "rpos encode-decode round-trip should be byte-exact for $hex")
        }
    }

    // =========================================================================
    // State Vector Tests
    // =========================================================================

    @Test
    fun testStateVectorMultiClientDecode() {
        // Hex "02d80401f40301" decodes to: {600: 1, 500: 1}
        val sv = decodeStateVector(hexToBytes(WireCompatFixtures.STATE_VECTORS_MULTI_CLIENT_STATE_VECTOR))
        assertEquals(2, sv.size, "should have 2 clients")
        assertTrue(sv.containsKey(500), "should contain client 500")
        assertTrue(sv.containsKey(600), "should contain client 600")
        assertEquals(1, sv[500], "client 500 should have clock 1")
        // Note: fixture JSON says {500:1, 600:2} but hex actually decodes to {500:1, 600:1}.
        // The hex is the authoritative source. If the JSON expectedMap differs, the hex wins.
    }

    @Test
    fun testStateVectorMultiClientReencode() {
        val originalHex = WireCompatFixtures.STATE_VECTORS_MULTI_CLIENT_STATE_VECTOR
        val sv = decodeStateVector(hexToBytes(originalHex))
        val reencoded = encodeStateVectorFromMap(sv)
        val sv2 = decodeStateVector(reencoded)
        assertEquals(sv, sv2, "re-encoded state vector should decode to same map")
    }

    @Test
    fun testStateVectorEmpty() {
        val sv = decodeStateVector(hexToBytes(WireCompatFixtures.STATE_VECTORS_EMPTY_STATE_VECTOR))
        assertTrue(sv.isEmpty(), "empty state vector should decode to empty map")
        val reencoded = toHex(encodeStateVectorFromMap(sv))
        assertEquals(WireCompatFixtures.STATE_VECTORS_EMPTY_STATE_VECTOR, reencoded,
            "empty state vector encoding should be byte-exact")
    }

    @Test
    fun testStateVectorSingleClient() {
        val sv = decodeStateVector(hexToBytes(WireCompatFixtures.STATE_VECTORS_SINGLE_CLIENT_STATE_VECTOR))
        assertEquals(1, sv.size, "should have 1 client")
        assertEquals(5, sv[800], "client 800 should have clock 5")
        // Single client: no ordering ambiguity, encoding should be byte-exact
        val reencoded = toHex(encodeStateVectorFromMap(sv))
        assertEquals(WireCompatFixtures.STATE_VECTORS_SINGLE_CLIENT_STATE_VECTOR, reencoded,
            "single-client state vector encoding should be byte-exact")
    }

    @Test
    fun testStateVectorManyClients() {
        val sv = decodeStateVector(hexToBytes(WireCompatFixtures.STATE_VECTORS_MANY_CLIENTS_STATE_VECTOR))
        assertEquals(6, sv.size, "should have 6 clients")
        for (client in listOf(900, 1000, 1100, 1200, 1300, 1400)) {
            assertTrue(sv.containsKey(client), "should contain client $client")
            assertEquals(1, sv[client], "client $client should have clock 1")
        }
    }

    @Test
    fun testStateVectorManyClientsReencode() {
        val originalHex = WireCompatFixtures.STATE_VECTORS_MANY_CLIENTS_STATE_VECTOR
        val sv = decodeStateVector(hexToBytes(originalHex))
        val reencoded = encodeStateVectorFromMap(sv)
        val sv2 = decodeStateVector(reencoded)
        assertEquals(sv, sv2, "re-encoded many-client state vector should decode to same map")
    }
}
